function.arguments:
{"command": "cat > /tmp/dump.py <<'EOF'
import sys,re
data=sys.stdin.read()
lines=data.split('\n')
for i,ln in enumerate(lines):
    if not ln.strip('\x1b[m0;123456789;2()?h') and ln=='' : 
        print(i, repr(ln)); continue
    parts=re.split(r'(\x1b\[[0-9;]*m)', ln)
    segs=[]
    cur=''
    for p in parts:
        if p.startswith('\x1b'):
            cur=p
        else:
            segs.append((cur.replace('\x1b','E'),p))
    # strip empty (E[0m,'')
    out=[]
    for c,t in segs:
        if t=='' and c in ('E[0m','E', ''): continue
        out.append((c,t))
    print(i, out)
EOF
cd /tmp/repo2 && /workspace/executable --no-art --no-color-palette 2>&1 | python3 /tmp/dump.py"}

