            pos=mm.end()
        else:
            # plain text until next escape
            nxt=ESC.search(ln, pos)
            end = nxt.start() if nxt else len(ln)
            tokens.append(('txt', ln[pos:end]))
            vis += end-pos
            pos=end
    # art region: accumulate visible length up to W
    art_tokens=[]; acc=0; i=0
    out=[]
    for kind,val in tokens:
        if kind=='esc':
            out.append(('esc',val))
        else:
            n=len(val)
            if acc+n >= W:
                keep = W-acc
                if keep>0: out.append(('txt', val[:keep]))
                break
            else:
                out.append(('txt', val)); acc+=n
    return out
