def art_segments(ln, W):
    pos=0; vis=0; out=[]
    while pos < len(ln):
        mm=ESC.match(ln,pos)
        if mm: out.append(('esc',mm.group(1))); pos=mm.end()
        else:
            nxt=ESC.search(ln,pos); end=nxt.start() if nxt else len(ln)
            chunk=ln[pos:end]
            if vis+len(chunk) >= W:
                keep=W-vis
                if keep>0: out.append(('txt',chunk[:keep]))
                break
            out.append(('txt',chunk)); vis+=len(chunk); pos=end
    return out
def segs_from(toks):
    segs=[]; cur=None; buf=''
    for kind,val in toks:
        if kind=='esc':
            if cur is not None or buf!='': segs.append([cur,buf])
            cur=val; buf=''
        else: buf+=val
    if cur is not None or buf!='': segs.append([cur,buf])
