#[derive(Clone, Copy, PartialEq)]
pub enum Color {
    Ansi(u8),
    Rgb(u8, u8, u8),
    Default,
}

impl Color {
    /// ANSI code string (without bold) for this color
    pub fn code(&self, truecolor: bool) -> String {
        match self {
            Color::Ansi(n) => {
                if *n < 8 {
                    format!("{}", 30 + *n)
                } else {
                    format!("{}", 90 + *n - 8)
                }
            }
            Color::Rgb(r, g, b) => {
                if truecolor {
                    format!("38;2;{};{};{}", r, g, b)
                } else {
                    // approximate with a palette color
                    let n = rgb_to_ansi(*r, *g, *b);
                    if n < 8 {
                        format!("{}", 30 + n)
                    } else {
                        format!("{}", 90 + n - 8)
                    }
                }
            }
            Color::Default => "39".to_string(),
        }
    }
    pub fn escape(&self, truecolor: bool, bold: bool) -> String {
        let mut c = self.code(truecolor);
        if bold {
            c.push_str(";1");
        }
        format!("\x1b[{}m", c)
    }
}

fn rgb_to_ansi(r: u8, g: u8, b: u8) -> u8 {
    // nearest of the 16 base colors (very rarely used)
    let palette: [(u8, u8, u8); 16] = [
        (0, 0, 0),
        (128, 0, 0),
        (0, 128, 0),
        (128, 128, 0),
        (0, 0, 128),
        (128, 0, 128),
        (0, 128, 128),
        (192, 192, 192),
        (128, 128, 128),
        (255, 0, 0),
        (0, 255, 0),
        (255, 255, 0),
        (0, 0, 255),
        (255, 0, 255),
        (0, 255, 255),
        (255, 255, 255),
    ];
    let mut best = 0u8;
    let mut bd = i64::MAX;
    for (i, p) in palette.iter().enumerate() {
        let d = (r as i64 - p.0 as i64).pow(2)
            + (g as i64 - p.1 as i64).pow(2)
            + (b as i64 - p.2 as i64).pow(2);
        if d < bd {
            bd = d;
            best = i as u8;
        }
    }
    best
}

pub use crate::langdata::{LANGS, ARTS, LangDef, ArtDef};

pub struct Language(pub usize);

impl Language {
    pub fn def(&self) -> &'static LangDef {
        &LANGS[self.0]
    }
    pub fn name(&self) -> &'static str {
        LANGS[self.0].name
    }
}

/// Find the language index for a given path (file name).
pub fn language_for(name: &str) -> Option<usize> {
    let lower = name.to_lowercase();
    // filename matches first
    for (i, l) in LANGS.iter().enumerate() {
        for f in l.files {
            if lower == *f {
                return Some(i);
            }
        }
    }
    let ext = match lower.rfind('.') {
        Some(p) => &lower[p + 1..],
        None => return None,
    };
    if ext.is_empty() {
        return None;
    }
    for (i, l) in LANGS.iter().enumerate() {
        for e in l.exts {
            if *e == ext {
                return Some(i);
            }
        }
    }
    None
}

/// Count lines of code of the given content following tokei-like rules.
pub fn count_code_lines(def: &LangDef, content: &str) -> usize {
    let mut count = 0usize;
    for line in content.split('\n') {
        if is_code_line(def, line) {
            count += 1;
        }
    }
    count
}

fn is_code_line(def: &LangDef, line: &str) -> bool {
    let bytes: Vec<char> = line.chars().collect();
    let mut i = 0usize;
    let mut found = false;
    while i < bytes.len() {
        // block comments
        let mut matched = false;
        for (start, end) in def.block_comments {
            let s: Vec<char> = start.chars().collect();
            if starts_with(&bytes, i, &s) {
                // skip to end token
                let e: Vec<char> = end.chars().collect();
                i += s.len();
                let mut j = i;
                let mut closed = false;
                while j < bytes.len() {
                    if starts_with(&bytes, j, &e) {
                        j += e.len();
                        closed = true;
                        break;
                    }
                    j += 1;
                }
                i = if closed { j } else { bytes.len() };
                matched = true;
                break;
            }
        }
        if matched {
            continue;
        }
        // line comments
        for lc in def.line_comments {
            let s: Vec<char> = lc.chars().collect();
            if starts_with(&bytes, i, &s) {
                return found;
            }
        }
        // strings: skip them (contents count as code)
        let c = bytes[i];
        if c == '"' || c == '\'' || c == '`' {
            let quote = c;
            i += 1;
            while i < bytes.len() {
                if bytes[i] == '\\' {
                    i += 2;
                    continue;
                }
                if bytes[i] == quote {
                    i += 1;
                    break;
                }
                i += 1;
            }
            found = true;
            continue;
        }
        if !c.is_whitespace() {
            found = true;
        }
        i += 1;
    }
    found
}

fn starts_with(hay: &[char], pos: usize, needle: &[char]) -> bool {
    if pos + needle.len() > hay.len() {
        return false;
    }
    for (k, ch) in needle.iter().enumerate() {
        if hay[pos + k] != *ch {
            return false;
        }
    }
    true
}
