pub fn humanize_delta(secs: i64, iso: bool, now: i64, target: i64) -> String {
    if iso {
        let t = target;
        return iso_format(t);
    }
    let d = target - now;
    let past = d >= 0;
    let a = d.abs();
    let s = fmt_dur(a);
    if past { format!("{} ago", s) } else { format!("in {}", s) }
}

fn iso_format(t: i64) -> String {
    // convert unix seconds to UTC ISO8601
    let days = t.div_euclid(86400);
    let secs = t.rem_euclid(86400);
    let (y, m, dd) = civil_from_days(days);
    format!("{:04}-{:02}-{:02}T{:02}:{:02}:{:02}Z", y, m, dd, secs / 3600, (secs % 3600) / 60, secs % 60)
}

pub fn civil_from_days(z: i64) -> (i64, u32, u32) {
    let z = z + 719468;
    let era = if z >= 0 { z } else { z - 146096 } / 146097;
    let doe = (z - era * 146097) as u64;
    let yoe = (doe - doe / 1460 + doe / 36524 - doe / 146096) / 365;
    let y = yoe as i64 + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let d = (doy - (153 * mp + 2) / 5 + 1) as u32;
    let m = if mp < 10 { mp + 3 } else { mp - 9 } as u32;
    (if m <= 2 { y + 1 } else { y }, m, d)
}

pub fn days_from_civil(y: i64, m: u32, d: u32) -> i64 {
    let y = if m <= 2 { y - 1 } else { y };
    let era = if y >= 0 { y } else { y - 399 } / 400;
    let yoe = y - era * 400;
    let mp = if m > 2 { m - 3 } else { m + 9 } as i64;
    let doy = (153 * mp + 2) / 5 + d as i64 - 1;
    let doe = yoe * 365 + yoe / 4 - yoe / 100 + doy;
    era * 146097 + doe - 719468
}

pub fn fmt_dur(a: i64) -> String {
    if a < 10 { return "now".to_string(); }
    if a < 46 { return format!("{} seconds", a); }
    if a < 91 { return "a minute".to_string(); }
    if a < 180 { return "2 minutes".to_string(); }
    if a < 2710 { return format!("{} minutes", a / 60); }
    if a < 5410 { return "an hour".to_string(); }
    if a < 10800 { return "2 hours".to_string(); }
    if a < 78000 { return format!("{} hours", a / 3600); }
    if a < 570000 {
        let d = a / 86400;
        return if d == 1 { "a day".to_string() } else { format!("{} days", d) };
    }
    if a < 2505600 {
        let w = a / 604800;
        return if w == 1 { "a week".to_string() } else { format!("{} weeks", w) };
    }
    if a < 29600000 {
        let m = a / 2592000;
        return if m == 1 { "a month".to_string() } else { format!("{} months", m) };
    }
    let y = a / 31536000;
    if y == 1 { "a year".to_string() } else { format!("{} years", y) }
}

pub struct Opts {
    pub path: Option<String>,
    pub disabled: Vec<String>,
    pub no_title: bool,
    pub number_of_authors: usize,
    pub number_of_languages: usize,
    pub number_of_file_churns: usize,
    pub churn_pool: Option<u32>,
    pub exclude: Vec<String>,
    pub no_bots: Option<Option<String>>,
    pub no_merges: bool,
    pub email: bool,
    pub http_url: bool,
    pub hide_token: bool,
    pub include_hidden: bool,
    pub types: Vec<String>,
    pub iso_time: bool,
    pub number_separator: String,
    pub no_bold: bool,
    pub ascii_input: Option<String>,
    pub ascii_colors: Option<Vec<u8>>,
    pub ascii_language: Option<String>,
    pub true_color: String,
    pub image: Option<String>,
    pub image_protocol: Option<String>,
    pub color_resolution: u32,
    pub no_color_palette: bool,
    pub no_art: bool,
    pub nerd_fonts: bool,
    pub output: Option<String>,
    pub text_colors: Option<Vec<u8>>,
}

pub fn now() -> i64 {
    std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).map(|d| d.as_secs() as i64).unwrap_or(0)
}

pub fn collect(o: &Opts) -> Result<Info, String> {
    let repo = git::open_repo(o.path.as_deref())?;
    let wd = repo.workdir.clone();
    let username = git::run_git(&["config", "--get", "user.name"], &wd).unwrap_or_default();
    let git_version = git::git_version();
    let url = git::remote_url(&wd).unwrap_or_default();
    let (repo_name_url, url_display) = process_url(&url, o.http_url, o.hide_token);
    let mut repo_name = repo_name_url;
    // package manager name fallback
    let (deps_count, deps_pm, pkg_name, description, version_from_pkg) = package_info(&wd);
    if repo_name.is_empty() {
        if let Some(n) = pkg_name { repo_name = n; }
    }
    let branches = git::branch_count(&wd);
    let tags = git::tag_count(&wd);
    let description = description;
    let (head_id, head_refs) = git::head_refs(&wd);
    let st = git::status_counts(&wd);
    let pending = (st.added, st.deleted, st.modified);
    let mut version = version_from_pkg.unwrap_or_default();
    if tags > 0 {
        if let Some(t) = git::run_git(&["tag", "--list", "--sort=refname"], &wd) {
            if let Some(first) = t.lines().find(|l| !l.trim().is_empty()) {
                version = first.trim().to_string();
            }
        }
    }
    let nowt = now();
    let created = match git::first_commit_time(&wd) {
        Some(t) => humanize_delta(0, o.iso_time, nowt, t.trim().parse().unwrap_or(nowt)),
        None => String::new(),
    };
    let last_change = match git::last_commit_time(&wd) {
        Some(t) => humanize_delta(0, o.iso_time, nowt, t.trim().parse().unwrap_or(nowt)),
        None => String::new(),
    };
    let shallow = git::is_shallow(&wd);
    let commits = git::commit_count(&wd, o.no_merges, None, false);
    // authors
    let mut extra: Vec<&str> = Vec::new();
    if o.no_merges { extra.push("--no-merges"); }
    let log = git::log_commits(&wd, &extra);
    let bot_re = o.no_bots.as_ref().map(|x| x.clone().unwrap_or_else(|| "\\bbot\\b".to_string()));
    let mut counts: Vec<(String, Option<String>, u32)> = Vec::new();
    let mut total_authors = 0u32;
    for c in &log {
        if let Some(re) = &bot_re { if is_bot(&c.author_name, re) { continue; } }
        total_authors += 1;
        match counts.iter_mut().find(|x| x.0 == c.author_name) {
            Some(e) => e.2 += 1,
            None => counts.push((c.author_name.clone(), if c.author_email.is_empty() { None } else { Some(c.author_email.clone()) }, 1)),
        }
    }
    counts.sort_by(|a, b| b.2.cmp(&a.2));
    let authors: Vec<(String, Option<String>, u32, u32)> = counts.iter().map(|(n, e, c)| {
        let pct = if total_authors > 0 { (( *c as f64 / total_authors as f64) * 100.0).round() as u32 } else { 0 };
        (n.clone(), e.clone(), *c, pct)
    }).collect();
    // languages + loc
    let (stats, loc) = lang::scan(&wd, o);
    let total_loc: usize = stats.iter().map(|s| s.loc).sum();
    let mut languages: Vec<(String, f64)> = Vec::new();
    for s in &stats {
        let pct = if total_loc > 0 { s.loc as f64 * 100.0 / total_loc as f64 } else { 0.0 };
        languages.push((Language(s.idx).def().json_name.to_string(), pct));
    }
    // churn
    let (churn, churn_pool) = churn_info(&wd, o, &log);
    // size
    let (size, file_count) = repo_size(&wd);
    let license = license_info(&wd);
    let art_lang = stats.first().map(|s| s.idx);
    Ok(Info {
        username, git_version, repo_name, branches, tags, description, head_id, head_refs,
        pending, version, created, deps: String::new(), deps_name: String::new(),
        deps_count, deps_pm, languages, loc: total_loc, authors, last_change,
        contributors: total_authors, url: url_display, commits, shallow, churn, churn_pool,
        size, file_count, license, art_lang,
    })
}

fn is_bot(name: &str, re: &str) -> bool {
    // support the simple patterns used: \bbot\b and user provided regex (plain substring fallback)
    if re == "\\bbot\\b" {
        let b: Vec<char> = name.chars().collect();
        let pat: Vec<char> = "bot".chars().collect();
        for i in 0..b.len() {
            if b.len() >= i + 3 && b[i..i+3] == pat[..] {
                let before_ok = i == 0 || !is_word(b[i-1]);
                let after_ok = i + 3 >= b.len() || !is_word(b[i+3]);
                if before_ok && after_ok { return true; }
            }
        }
        return false;
    }
    name.contains(re)
}

fn is_word(c: char) -> bool { c.is_alphanumeric() || c == '_' }

fn process_url(url: &str, http_url: bool, hide_token: bool) -> (String, String) {
    let mut u = url.to_string();
    if u.is_empty() { return (String::new(), String::new()); }
    if http_url {
        // scp-like form: user@host:path (no scheme)
        if !u.contains("://") {
            if let Some(pos) = u.find(':') {
                if let Some(at) = u.find('@') {
                    if at < pos {
                        let host = &u[..pos];
                        let path = &u[pos+1..];
                        u = format!("https://{}/{}", host, path);
                    }
                }
            }
        }
    }
    // extract repo name from the path
    let name = {
        let path = if let Some(p) = u.find("://") {
            let rest = &u[p+3..];
            match rest.find('/') { Some(i) => &rest[i+1..], None => "" }
        } else if let Some(p) = u.find(':') {
            &u[p+1..]
        } else { "" };
        let path = path.split('#').next().unwrap_or("");
        let path = path.split('?').next().unwrap_or("");
        let stem = match path.rfind('/') {
            Some(i) => &path[i+1..],
            None => path,
        };
        rust_file_stem(stem).to_string()
    };
    // userinfo handling
    let mut display = u.clone();
    if let Some(p) = u.find("://") {
        let scheme_end = p + 3;
        let rest = &u[scheme_end..];
        if let Some(at) = rest.find('@') {
            let userinfo = &rest[..at];
            let after = &rest[at..];
            let newinfo = if hide_token {
                String::new()
            } else {
                match userinfo.find(':') {
                    Some(i) => format!("{}:redacted", encode_userinfo(&userinfo[..i])),
                    None => encode_userinfo(userinfo),
                }
            };
            display = format!("{}{}{}", &u[..scheme_end], newinfo, after);
        }
    }
    (name, display)
}

fn rust_file_stem(s: &str) -> &str {
    match s.rfind('.') {
        Some(0) => s,
        Some(i) => &s[..i],
        None => s,
    }
}

fn encode_userinfo(s: &str) -> String {
    let mut out = String::new();
    let b: Vec<char> = s.chars().collect();
    let mut i = 0;
    while i < b.len() {
        let c = b[i];
        if c == '%' && i + 2 < b.len() && b[i+1].is_ascii_hexdigit() && b[i+2].is_ascii_hexdigit() {
            out.push(c); out.push(b[i+1]); out.push(b[i+2]);
            i += 3;
            continue;
        }
        if c.is_ascii_alphanumeric() { out.push(c); }
        else {
            let mut buf = [0u8; 4];
            for byte in c.encode_utf8(&mut buf).as_bytes() {
                out.push_str(&format!("%{:02X}", byte));
            }
        }
        i += 1;
    }
    out
}

pub fn package_info(wd: &Path) -> (usize, String, Option<String>, Option<String>, Option<String>) {
    // Cargo first, then Npm
    if let Some(txt) = read_index(wd, "Cargo.toml") {
        if let Some((v, n, d, cnt)) = parse_cargo(&txt) {
            return (cnt, "Cargo".to_string(), n, d, v);
        }
    }
    if let Some(txt) = read_index(wd, "package.json") {
        if let Some((v, n, d, cnt)) = parse_package_json(&txt) {
            return (cnt, "Npm".to_string(), n, d, v);
        }
    }
    (0, String::new(), None, None, None)
}

pub fn read_index(wd: &Path, path: &str) -> Option<String> {
    // read from worktree if present, else from index
    let p = wd.join(path);
    if p.exists() {
        if let Ok(s) = std::fs::read_to_string(&p) { return Some(s); }
    }
    git::blob_content(wd, path)
}

fn parse_cargo(txt: &str) -> Option<(Option<String>, Option<String>, Option<String>, usize)> {
    // minimal TOML parse: find [package] table, then version/name/description; count [dependencies] entries
    let mut section = String::new();
    let mut version = None; let mut name = None; let mut descr = None;
    let mut in_deps = false; let mut count = 0;
    for line in txt.lines() {
        let l = line.trim();
        if l.starts_with('#') || l.is_empty() { continue; }
        if l.starts_with('[') {
            let end = l.find(']').unwrap_or(l.len());
            section = l[1..end].trim().to_string();
            in_deps = section == "dependencies";
            continue;
        }
        if let Some(eq) = l.find('=') {
            let key = l[..eq].trim().trim_matches('"').to_string();
            let val = l[eq+1..].trim().to_string();
            if section == "package" {
                match key.as_str() {
                    "version" => version = Some(unquote(&val)),
                    "name" => name = Some(unquote(&val)),
                    "description" => descr = Some(unquote(&val)),
                    _ => {}
                }
            }
            if in_deps && !key.is_empty() { count += 1; }
        }
    }
    version?;
    Some((version, name, descr, count))
}

fn unquote(s: &str) -> String {
    let s = s.trim();
    if s.len() >= 2 && ((s.starts_with('"') && s.ends_with('"')) || (s.starts_with('\'') && s.ends_with('\''))) {
        s[1..s.len()-1].to_string()
    } else { s.to_string() }
}

fn parse_package_json(txt: &str) -> Option<(Option<String>, Option<String>, Option<String>, usize)> {
    let version = json_string_field(txt, "version")?;
    let name = json_string_field(txt, "name");
    let descr = json_string_field(txt, "description");
    let cnt = json_object_len(txt, "dependencies");
    Some((Some(version), name, descr, cnt))
}

fn json_string_field(txt: &str, key: &str) -> Option<String> {
    let pat = format!("\"{}\"", key);
    let mut search_from = 0;
    while let Some(p) = txt[search_from..].find(&pat) {
        let abs = search_from + p;
        let rest = &txt[abs + pat.len()..];
        let rest = rest.trim_start();
        if let Some(st) = rest.strip_prefix(':') {
            let st = st.trim_start();
            if let Some(v) = st.strip_prefix('"') {
                if let Some(e) = v.find('"') { return Some(v[..e].to_string()); }
            }
        }
        search_from = abs + pat.len();
    }
    None
}

fn json_object_len(txt: &str, key: &str) -> usize {
    let pat = format!("\"{}\"", key);
    let mut search_from = 0;
    while let Some(p) = txt[search_from..].find(&pat) {
        let abs = search_from + p;
        let rest = &txt[abs + pat.len()..].trim_start();
        if let Some(st) = rest.strip_prefix(':') {
            let st = st.trim_start();
            if let Some(v) = st.strip_prefix('{') {
                // count top-level "key": pairs
                let mut depth = 0; let mut cnt = 0; let mut in_str = false; let mut esc = false;
                for c in v.chars() {
                    if esc { esc = false; continue; }
                    match c {
                        '\\' if in_str => esc = true,
                        '"' => in_str = !in_str,
                        '{' | '[' if !in_str => depth += 1,
                        '}' | ']' if !in_str => { if depth == 0 { return cnt; } depth -= 1; }
                        ',' if !in_str && depth == 0 => cnt += 1,
                        _ => {}
                    }
                }
                return cnt;
            }
        }
        search_from = abs + pat.len();
    }
    0
}

pub fn repo_size(wd: &Path) -> (u64, u32) {
    let files = git::ls_files(wd);
    let mut total = 0u64; let mut count = 0u32;
    for f in &files {
        let name = f.rsplit('/').next().unwrap_or("");
        let lower = name.to_lowercase();
        if lower.contains("license") || lower.contains("licence") || lower.starts_with("copying") { continue; }
        if let Some(s) = git::blob_size(wd, f) { total += s; count += 1; }
    }
    (total, count)
}

pub fn license_info(wd: &Path) -> String {
    let files = git::ls_files(wd);
    for f in &files {
        let name = f.rsplit('/').next().unwrap_or("").to_lowercase();
        if !(name.contains("license") || name.contains("licence") || name.starts_with("copying")) { continue; }
        if let Some(content) = git::blob_content(wd, f) {
            if let Some(l) = match_license(&content) { return l.to_string(); }
        }
    }
    String::new()
}

const MIT_TEXT: &str = include_str!("../data/mit_license.txt");

fn match_license(content: &str) -> Option<&'static str> {
    let tlines: Vec<&str> = MIT_TEXT.lines().map(|l| l.trim()).collect();
    let tchars: usize = tlines.iter().map(|l| l.chars().count()).sum();
    let flines: Vec<&str> = content.lines().map(|l| l.trim()).collect();
    let mut matched = 0usize;
    let mut fchars = 0usize;
    for l in &flines {
        fchars += l.chars().count();
        if tlines.iter().any(|t| !t.is_empty() && (l.contains(t) || t.contains(l) || similar(l, t))) {
            matched += l.chars().count();
        }
    }
    let denom = std::cmp::max(fchars, tchars);
    if denom > 0 && (matched as f64 / denom as f64) >= 0.7 { Some("MIT") } else { None }
}

fn similar(a: &str, b: &str) -> bool {
    let aw: Vec<&str> = a.split_whitespace().collect();
    let bw: Vec<&str> = b.split_whitespace().collect();
    if aw.len() < 3 || bw.len() < 3 { return false; }
    let common = aw.iter().filter(|w| bw.contains(w)).count();
    common * 2 >= aw.len() + bw.len() - 2
}

pub fn churn_info(wd: &Path, o: &Opts, log: &[git::CommitInfo]) -> (Vec<(String, u32)>, u32) {
    let total = log.len() as u32;
    let default_pool = default_churn_pool(total);
    let mut pool = o.churn_pool.unwrap_or(0);
    pool = std::cmp::max(pool, default_pool);
    if pool > total { pool = total; }
    let mut map: std::collections::HashMap<String, u32> = std::collections::HashMap::new();
    let mut order: Vec<String> = Vec::new();
    for c in log.iter().take(pool as usize) {
        let parent = if c.hash.is_empty() { String::new() } else { String::new() };
        let _ = parent;
    }
    // compute changed files per commit using git diff-tree
    let hashes: Vec<&str> = log.iter().take(pool as usize).map(|c| c.hash.as_str()).collect();
    if !hashes.is_empty() {
        let mut args: Vec<String> = vec!["diff-tree".into(), "--no-commit-id".into(), "--name-only".into(), "-r".into()];
        args.extend(hashes.iter().map(|h| h.to_string()));
        let argv: Vec<&str> = args.iter().map(|s| s.as_str()).collect();
        if let Some(out) = git::run_git(&argv, wd) {
            for line in out.lines() {
                if line.is_empty() { continue; }
                let e = map.entry(line.to_string()).or_insert(0);
                *e += 1;
            }
        }
    }
    let mut v: Vec<(String, u32)> = map.into_iter().collect();
    v.sort_by(|a, b| b.1.cmp(&a.1).then(a.0.cmp(&b.0)));
    v.truncate(o.number_of_file_churns);
    (v, pool)
}

pub fn default_churn_pool(total: u32) -> u32 {
    if total < 46 { return 1; }
    let v = total / 4;
    if v > 6 { v - 6 } else { 1 }
}
