pub struct ScanOpts { pub include_hidden: bool, pub types: u8, pub exclude: Vec<String>, pub max_langs: usize }

/// Scan the working tree for languages and lines of code.
pub fn scan(wd: &std::path::Path, o: &crate::info::Opts) -> (Vec<LangStat>, usize) {
    let files = crate::git::all_files(wd);
    let mut per: std::collections::HashMap<usize, usize> = std::collections::HashMap::new();
    let mut order: Vec<usize> = Vec::new();
    let mut excluded: Vec<String> = o.exclude.iter().map(|e| e.to_lowercase()).collect();
    for f in &files {
        let name = f.rsplit('/').next().unwrap_or(f);
        if !o.include_hidden && name.starts_with('.') { continue; }
        // skip if any parent dir is hidden
        if !o.include_hidden && f.split('/').any(|c| c.starts_with('.')) { continue; }
        if excluded.iter().any(|e| {
            let fl = f.to_lowercase();
            fl == *e || fl.starts_with(&format!("{}/", e)) || fl.ends_with(&format!("/{}", e)) || fl.contains(&format!("/{}/", e))
        }) { continue; }
        let idx = match language_for(name) { Some(i) => i, None => continue };
        let def = &LANGS[idx];
        if def.types & crate::info::type_mask(&o.types) == 0 { continue; }
        let path = wd.join(f);
        let content = match std::fs::read_to_string(&path) { Ok(c) => c, Err(_) => continue };
        let n = count_code_lines(def, &content);
        if n == 0 { continue; }
        match per.get_mut(&idx) { Some(v) => *v += n, None => { per.insert(idx, n); order.push(idx); } }
    }
    let mut stats: Vec<LangStat> = per.iter().map(|(k, v)| LangStat { idx: *k, loc: *v }).collect();
    stats.sort_by(|a, b| {
        b.loc.cmp(&a.loc)
            .then(order.iter().position(|x| *x == a.idx).unwrap_or(0).cmp(&order.iter().position(|x| *x == b.idx).unwrap_or(0)))
    });
    let total: usize = stats.iter().map(|s| s.loc).sum();
    (stats, total)
}
