                title.push_str(" ~ ");
                title.push_str(&info.git_version);
            }
        }
        let n = title.chars().count();
        let dashes: String = std::iter::repeat('-').take(n).collect();
        row.push((Some(underline_c), dashes));
        row.push((Some(underline_c), String::new()));
        rows.push(row);
    }
    // info rows
    let infos = build_info_rows(info, o, &subtitle_c, &colon_c, &info_c, w);
    for r in infos {
        let mut row: Vec<(Option<Color>, String)> = Vec::new();
        if k < art_lines.len() { push_art_row(&mut row, &art_lines[k], &art_colors); k += 1; }
        pad_row(&mut row, art_w);
        for s in r { row.push(s); }
        rows.push(row);
    }
    // remaining art lines
    while k < art_lines.len() {
        let mut row: Vec<(Option<Color>, String)> = Vec::new();
        push_art_row(&mut row, &art_lines[k], &art_colors);
        k += 1;
        pad_row(&mut row, art_w);
        rows.push(row);
    }
    // color palette
    if !o.no_color_palette {
        while rows.len() < nlines { rows.push(Vec::new()); }
        let mut row: Vec<(Option<Color>, String)> = Vec::new();
        if k < art_lines.len() { push_art_row(&mut row, &art_lines[k], &art_colors); k += 1; }
        pad_row(&mut row, art_w);
        rows.push(row);
        let last = rows.len() - 1;
        for i in 0..8u8 {
            rows[last].push((Some(Color::Ansi(i + 40 - 40)), String::new()));
            rows[last].push((Some(Color::Ansi(i)), "   ".to_string()));
            rows[last].push((Some(Color::Ansi(49)), String::new()));
        }
    }
    for (i, row) in rows.iter().enumerate() {
        if i > 0 { w.plain("\n"); }
        emit_row(w, row);
    }
    w.plain("\n\x1b[?7h\n");
}

fn lang_slug_matches(_a: &&crate::langdata::ArtDef, _slug: &str) -> bool { true }

pub fn hexval(c: char) -> usize {
    match c { '0'..='9' => c as usize - '0' as usize, 'a'..='f' => c as usize - 'a' as usize + 10, _ => 0 }
}

fn art_lang_index(info: &Info, o: &Opts) -> Option<usize> {
    if let Some(l) = &o.ascii_language {
        for (i, d) in LANGS.iter().enumerate() { if d.slug == *l { return Some(i); } }
    }
    info.art_lang
}

fn push_art_row(row: &mut Vec<(Option<Color>, String)>, art: &[(usize, String)], colors: &[Color]) {
    row.push((Some(Color::Default), String::new()));
    for (idx, txt) in art {
        let c = colors.get(*idx).cloned().unwrap_or(Color::Default);
        row.push((Some(c), txt.clone()));
    }
}

fn pad_row(row: &mut Vec<(Option<Color>, String)>, w: usize) {
    let cur: usize = row.iter().map(|(_, t)| t.chars().count()).sum();
    if cur < w { row.push((None, " ".repeat(w - cur))); }
}

fn emit_row(w: &mut W, row: &[(Option<Color>, String)]) {
    for (c, t) in row {
        match c {
            Some(col) => w.seg(col, t),
            None => w.plain(t),
        }
    }
}

pub type Seg = (Option<Color>, String);

pub fn build_info_rows(info: &Info, o: &Opts, sub: &Color, col: &Color, inf: &Color, w: &W)
    -> Vec<Vec<Seg>>
{
    let mut rows: Vec<Vec<Seg>> = Vec::new();
    let mut label = |rows: &mut Vec<Vec<Seg>>, name: &str, content: Vec<Seg>| {
        let mut first: Vec<Seg> = Vec::new();
        first.push((Some(sub.clone()), name.to_string()));
        first.push((Some(col.clone()), ":".to_string()));
        first.push((None, " ".to_string()));
        for s in content { first.push(s); }
        rows.push(first);
    };
    let indent_for = |name: &str| format!("{}{}", name, ": ".to_string());
    let cont = |rows: &mut Vec<Vec<Seg>>, name: &str, content: Vec<Seg>| {
        let mut r: Vec<Seg> = Vec::new();
        r.push((Some(inf.clone()), indent_for(name)));
        for s in content { r.push(s); }
        rows.push(r);
    };
    let disabled = |n: &str| o.disabled.iter().any(|d| d == n);

    // Project
    if !disabled("project") && (!info.repo_name.is_empty() || info.branches > 0 || info.tags > 0) {
        let mut s = info.repo_name.clone();
        if info.branches > 0 { s.push_str(&format!(" ({} branches)", info.branches)); }
        if info.tags > 0 { s.push_str(&format!(" ({} tags)", info.tags)); }
        let parts = plural_parts(&s, "project", info.branches, info.tags);
        let mut it = parts.into_iter();
        if let Some(f) = it.next() { label(&mut rows, "Project", vec![(Some(inf.clone()), f)]); }
        for p in it { cont(&mut rows, "Project", vec![(Some(inf.clone()), p)]); }
    }
    if let Some(d) = &info.description {
        if !disabled("description") && !d.is_empty() {
            label(&mut rows, "Description", vec![(Some(inf.clone()), d.clone())]);
        }
    }
    if !disabled("head") {
        let mut s = info.head_id.clone();
        if !info.head_refs.is_empty() {
            s.push_str(&format!(" ({})", info.head_refs.join(", ")));
        }
        label(&mut rows, "HEAD", vec![(Some(inf.clone()), s)]);
    }
    if !disabled("pending") {
        let (a, d, m) = info.pending;
        let mut parts: Vec<String> = Vec::new();
        if m > 0 { parts.push(format!("{}+-", m)); }
        if a > 0 { parts.push(format!("{}+", a)); }
        if d > 0 { parts.push(format!("{}-", d)); }
        if !parts.is_empty() {
            let joined = parts.join(" ");
            label(&mut rows, "Pending", vec![(Some(inf.clone()), joined)]);
        }
    }
    if !disabled("version") && !info.version.is_empty() {
        label(&mut rows, "Version", vec![(Some(inf.clone()), info.version.clone())]);
    }
    if !disabled("created") && !info.created.is_empty() {
        label(&mut rows, "Created", vec![(Some(inf.clone()), info.created.clone())]);
    }
    if !disabled("dependencies") && info.deps_count > 0 {
        label(&mut rows, "Dependencies", vec![(Some(inf.clone()), format!("{} ({})", info.deps_count, info.deps_pm))]);
    }
    if !disabled("languages") && !info.languages.is_empty() {
        let name = if info.languages.len() == 1 { "Language" } else { "Languages" };
        // bar
        let mut bar: Vec<Seg> = Vec::new();
        bar.push((Some(inf.clone()), String::new()));
        let shown: Vec<(usize, f64)> = {
            let n = info.languages.len();
            let take = std::cmp::min(o.number_of_languages, n);
            let mut v: Vec<(usize, f64)> = (0..take).map(|i| (i, info.languages[i].1)).collect();
            if n > take + 1 {
                let rest: f64 = info.languages[take..].iter().map(|x| x.1).sum();
                v.push((usize::MAX, rest));
            } else if n > take {
                v.push((take, info.languages[take].1));
            }
            v
        };
        for (i, (_idx, pct)) in shown.iter().enumerate() {
            let c = if *_idx == usize::MAX { Color::Ansi(7) } else {
                if w.truecolor { Color::Rgb(LANGS[lang_index_of(info, *_idx)].rgb.0, LANGS[lang_index_of(info, *_idx)].rgb.1, LANGS[lang_index_of(info, *_idx)].rgb.2) } else { Color::Ansi((1 + i % 6) as u8) }
            };
            let cells = (pct * 26.0 / 100.0).round() as usize;
            bar.push((Some(Color::Ansi(10 + c.code_no() as u8)), " ".repeat(cells)));
            bar.push((Some(Color::Ansi(49)), String::new()));
        }
        label(&mut rows, name, bar);
        // legend lines: 2 per row
        let mut legend: Vec<Seg> = Vec::new();
        for (i, (idx, pct)) in shown.iter().enumerate() {
            if i > 0 && i % 2 == 0 {
                rows.push(legend); legend = Vec::new();
                legend.push((Some(inf.clone()), " ".repeat(name.len() + 2)));
            } else if i == 0 {
                legend.push((Some(inf.clone()), " ".repeat(name.len() + 2)));
            } else {
                legend.push((Some(inf.clone()), " ".to_string()));
            }
            let is_other = *idx == usize::MAX;
            let c = if is_other { Color::Ansi(7) } else {
                if w.truecolor { let li = lang_index_of(info, *idx); Color::Rgb(LANGS[li].rgb.0, LANGS[li].rgb.1, LANGS[li].rgb.2) } else { Color::Ansi((1 + i % 6) as u8) }
            };
            let chip = if is_other { "\u{25cf}".to_string() } else if o.nerd_fonts {
                let li = lang_index_of(info, *idx);
                LANGS[li].nerd.map(|c| c.to_string()).unwrap_or_else(|| "\u{25cf}".to_string())
            } else { "\u{25cf}".to_string() };
            legend.push((Some(c), chip));
            legend.push((Some(inf.clone()), " ".to_string()));
            let nm = if is_other { "Other".to_string() } else {
                let li = lang_index_of(info, *idx);
                LANGS[li].name.to_string()
            };
            legend.push((Some(inf.clone()), format!("{} ({:.1} %)", nm, pct)));
            legend.push((Some(inf.clone()), " ".to_string()));
        }
        if !legend.is_empty() { rows.push(legend); }
    }
    if !disabled("authors") && !info.authors.is_empty() {
        let name = if info.authors.len() == 1 { "Author" } else { "Authors" };
        let mut items: Vec<String> = Vec::new();
        for (n, e, c, pct) in info.authors.iter().take(o.number_of_authors) {
            let mut s = format!("{}% ", pct);
            s.push_str(n);
            if o.email { if let Some(e) = e { s.push_str(&format!(" <{}>", e)); } }
            s.push_str(&format!(" {}", c));
            items.push(s);
        }
        let mut it = items.into_iter();
        if let Some(f) = it.next() { label(&mut rows, name, vec![(Some(inf.clone()), f)]); }
        for p in it { cont(&mut rows, name, vec![(Some(inf.clone()), p)]); }
    }
    if !disabled("last-change") && !info.last_change.is_empty() {
        label(&mut rows, "Last change", vec![(Some(inf.clone()), info.last_change.clone())]);
    }
    if !disabled("contributors") && info.contributors > 1 {
        label(&mut rows, "Contributors", vec![(Some(inf.clone()), format!("{}", info.contributors))]);
    }
    if !disabled("url") && !info.url.is_empty() {
        label(&mut rows, "URL", vec![(Some(inf.clone()), info.url.clone())]);
    }
    if !disabled("commits") && info.commits > 0 {
        let mut s = format!("{}", info.commits);
        if info.shallow { s.push_str(" (shallow)"); }
        label(&mut rows, "Commits", vec![(Some(inf.clone()), s)]);
    }
    if !disabled("churn") && !info.churn.is_empty() {
        let name = format!("Churn ({})", info.churn_pool);
        let mut items: Vec<String> = Vec::new();
        for (f, c) in &info.churn { items.push(format!("{} {}", f, c)); }
        let mut it = items.into_iter();
        if let Some(f) = it.next() { label(&mut rows, &name, vec![(Some(inf.clone()), f)]); }
        for p in it { cont(&mut rows, &name, vec![(Some(inf.clone()), p)]); }
    }
    if !disabled("lines-of-code") && info.loc > 0 {
        label(&mut rows, "Lines of code", vec![(Some(inf.clone()), with_sep(info.loc as u64, &o.number_separator))]);
    }
    if !disabled("size") && info.file_count > 0 {
        let s = format!("{} ({} files)", format_size(info.size, &o.number_separator), with_sep(info.file_count as u64, &o.number_separator));
        label(&mut rows, "Size", vec![(Some(inf.clone()), s)]);
    }
    if !disabled("license") && !info.license.is_empty() {
        label(&mut rows, "License", vec![(Some(inf.clone()), info.license.clone())]);
    }
    rows
}

fn lang_index_of(info: &Info, json_pos: usize) -> usize {
    // info.languages stores json_name; map position -> language index via art_lang/langs
    // we need the language idx; recompute from scan order is not available here,
    // so store indices in Info instead (see info.rs languages_idx)
    info.langs_idx.get(json_pos).cloned().unwrap_or(0)
}

fn plural_parts(s: &str, _f: &str, _b: u32, _t: u32) -> Vec<String> { vec![s.to_string()] }

impl Color { pub fn code_no(&self) -> u8 { match self { Color::Ansi(n) => *n, Color::Rgb(r, g, b) => crate::lang::rgb_to_ansi(*r, *g, *b), Color::Default => 39 } } }
