    s.push_str("  },\n");
    s.push_str("  \"infoFields\": [\n");
    let mut fields: Vec<String> = Vec::new();
    if !disabled(o, "project") {
        fields.push(format!("    {{\n      \"ProjectInfo\": {\n        \"repoName\": {},\n        \"numberOfBranches\": {},\n        \"numberOfTags\": {}\n      }\n    }}", q(&info.repo_name), info.branches, info.tags));
    }
    if !disabled(o, "description") {
        let d = match &info.description { Some(d) => q(d), None => "null".to_string() };
        fields.push(format!("    {{\n      \"DescriptionInfo\": {\n        \"description\": {}\n      }\n    }}", d));
    }
    if !disabled(o, "head") {
        let refs: Vec<String> = info.head_refs.iter().map(|r| format!("        {}", q(r))).collect();
        fields.push(format!("    {{\n      \"HeadInfo\": {\n        \"headRefs\": {{\n          \"shortCommitId\": {},\n          \"refs\": [\n{}\n          ]\n        }}\n      }}\n    }}", q(&info.head_id), refs.join(",\n")));
    }
    if !disabled(o, "pending") {
        fields.push(format!("    {{\n      \"PendingInfo\": {{\n        \"added\": {},\n        \"deleted\": {},\n        \"modified\": {}\n      }}\n    }}", info.pending.0, info.pending.1, info.pending.2));
    }
