use crate::info::Opts;

pub const FIELDS: &[&str] = &["project", "description", "head", "pending", "version", "created", "languages", "dependencies", "authors", "last-change", "contributors", "url", "commits", "churn", "lines-of-code", "size", "license"];
pub const TYPES: &[&str] = &["programming", "markup", "prose", "data"];
pub const SEPARATORS: &[&str] = &["plain", "comma", "space", "underscore"];
pub const TRUECOLORS: &[&str] = &["auto", "never", "always"];
pub const IMAGE_PROTOCOLS: &[&str] = &["kitty", "sixel", "iterm"];
pub const COLOR_RESOLUTIONS: &[&str] = &["16", "32", "64", "128", "256"];
pub const OUTPUTS: &[&str] = &["json", "yaml"];
pub const SHELLS: &[&str] = &["bash", "elvish", "fish", "powershell", "zsh"];

pub enum Action {
    Help(bool),
    Version,
    Generate(String),
    Languages,
    PackageManagers,
    Run(Box<Opts>),
}

fn err_invalid(v: &str, opt: &str, possible: &[&str]) -> String {
    format!("error: invalid value '{}' for '--{}'\n  [possible values: {}]\n\nFor more information, try '--help'.\n", v, opt, possible.join(", "))
}

fn err_invalid_range(v: &str, opt: &str) -> String {
    format!("error: invalid value '{}' for '--{}': {} is not in 0..16\n\nFor more information, try '--help'.\n", v, opt, v)
}

fn err_num(v: &str, opt: &str) -> String {
    format!("error: invalid value '{}' for '--{} <NUM>': invalid digit found in string\n\nFor more information, try '--help'.\n", v, opt)
}

fn err_unexpected(a: &str) -> String {
    format!("error: unexpected argument '{}' found\n\n  tip: to pass '{}' as a value, use '-- {}'\n\nFor more information, try '--help'.\n", a, a, a)
}

struct P { i: usize, argv: Vec<String> }

impl P {
    fn peek(&self) -> Option<&String> { self.argv.get(self.i) }
    fn next(&mut self) -> Option<String> { let v = self.argv.get(self.i).cloned(); if v.is_some() { self.i += 1; } v }
    fn has(&self) -> bool { self.i < self.argv.len() }
}

pub fn parse(argv: &[String]) -> Result<Action, String> {
    let mut o = Opts::default();
    let mut pos: Vec<String> = Vec::new();
    let mut p = P { i: 0, argv: argv.to_vec() };
    let mut num_languages: usize = 6;
    let mut num_authors: usize = 3;
    let mut num_churns: usize = 3;
    while p.has() {
        let a = p.next().unwrap();
        if a == "--" {
            while p.has() { pos.push(p.next().unwrap()); }
            break;
        }
        if let Some(rest) = a.strip_prefix("--") {
            let (name, inline) = match rest.find('=') {
                Some(k) => (&rest[..k], Some(rest[k+1..].to_string())),
                None => (rest, None),
            };
            match name {
                "help" => return Ok(Action::Help(true)),
                "version" => return Ok(Action::Version),
                "no-title" => o.no_title = true,
                "no-merges" => o.no_merges = true,
                "email" => o.email = true,
                "http-url" => o.http_url = true,
                "hide-token" => o.hide_token = true,
                "include-hidden" => o.include_hidden = true,
                "iso-time" => o.iso_time = true,
                "no-bold" => o.no_bold = true,
                "no-color-palette" => o.no_color_palette = true,
                "no-art" => o.no_art = true,
                "nerd-fonts" => o.nerd_fonts = true,
                "languages" => return Ok(Action::Languages),
                "package-managers" => return Ok(Action::PackageManagers),
                "number-of-authors" => num_authors = get_num(&mut p, inline, "number-of-authors")?,
                "number-of-languages" => num_languages = get_num(&mut p, inline, "number-of-languages")?,
                "number-of-file-churns" => num_churns = get_num(&mut p, inline, "number-of-file-churns")?,
                "churn-pool-size" => o.churn_pool = Some(get_num(&mut p, inline, "churn-pool-size")? as u32),
                "no-bots" => o.no_bots = Some(inline),
                "disabled-fields" => {
                    for v in get_list(&mut p, inline, true)? { validate(&v, FIELDS, "disabled-fields")?; o.disabled.push(v); }
                }
                "exclude" => { for v in get_list(&mut p, inline, true)? { o.exclude.push(v); } }
                "type" => {
                    let mut got = false;
                    for v in get_list(&mut p, inline, true)? { validate(&v, TYPES, "type")?; o.types.push(v); got = true; }
                    let _ = got;
                }
                "text-colors" => o.text_colors = Some(get_colors(&mut p, inline, "text-colors")?),
                "number-separator" => { let v = get_one(&mut p, inline); validate(&v, SEPARATORS, "number-separator")?; o.number_separator = v; }
                "ascii-input" => { let v = get_one(&mut p, inline); if v.is_empty() { return Err("error: a value is required for '--ascii-input <STRING>' but none was supplied\n\nFor more information, try '--help'.\n".to_string()); } o.ascii_input = Some(v); }
                "ascii-colors" => o.ascii_colors = Some(get_colors(&mut p, inline, "ascii-colors")?),
                "ascii-language" => { let v = get_one(&mut p, inline); if crate::lang::slug_index(&v).is_none() { return Err(err_invalid(&v, "ascii-language <LANGUAGE>", &crate::lang::slug_list_vec())); } o.ascii_language = Some(v); }
                "true-color" => { let v = get_one(&mut p, inline); validate(&v, TRUECOLORS, "true-color <WHEN>")?; o.true_color = v; }
                "image" => { o.image = Some(get_one(&mut p, inline)); }
                "image-protocol" => { let v = get_one(&mut p, inline); validate(&v, IMAGE_PROTOCOLS, "image-protocol <PROTOCOL>")?; o.image_protocol = Some(v); }
                "color-resolution" => { let v = get_one(&mut p, inline); validate(&v, COLOR_RESOLUTIONS, "color-resolution <VALUE>")?; o.color_resolution = v.parse().unwrap(); }
                "output" => { let v = get_one(&mut p, inline); validate(&v, OUTPUTS, "output <FORMAT>")?; o.output = Some(v); }
                "generate" => { let v = get_one(&mut p, inline); validate(&v, SHELLS, "generate <SHELL>")?; return Ok(Action::Generate(v)); }
                _ => return Err(err_unexpected(&a)),
            }
            continue;
        }
        if a.len() > 1 && a.starts_with('-') {
            let chars: Vec<char> = a[1..].chars().collect();
            let mut k = 0usize;
            let mut consumed = false;
            while k < chars.len() {
                let c = chars[k];
                match c {
                    'h' => return Ok(Action::Help(false)),
                    'V' => return Ok(Action::Version),
                    'E' => o.email = true,
                    'z' => o.iso_time = true,
                    'l' => return Ok(Action::Languages),
                    'p' => return Ok(Action::PackageManagers),
                    'd' | 'e' | 'T' | 't' | 'c' | 'a' | 'i' | 'o' => {
                        let rest: String = chars[k+1..].iter().collect();
                        let inline = if rest.is_empty() { None } else { Some(rest) };
                        let opt = match c { 'd' => "disabled-fields", 'e' => "exclude", 'T' => "type", 't' => "text-colors", 'c' => "ascii-colors", 'a' => "ascii-language", 'i' => "image", _ => "output" };
                        match c {
                            'd' => { for v in get_list(&mut p, inline, true)? { validate(&v, FIELDS, "disabled-fields")?; o.disabled.push(v); } }
                            'e' => { for v in get_list(&mut p, inline, true)? { o.exclude.push(v); } }
                            'T' => { for v in get_list(&mut p, inline, true)? { validate(&v, TYPES, "type")?; o.types.push(v); } }
                            't' => o.text_colors = Some(get_colors(&mut p, inline, "text-colors")?),
                            'c' => o.ascii_colors = Some(get_colors(&mut p, inline, "ascii-colors")?),
                            'a' => { let v = get_one(&mut p, inline); if crate::lang::slug_index(&v).is_none() { return Err(err_invalid(&v, "ascii-language <LANGUAGE>", &crate::lang::slug_list_vec())); } o.ascii_language = Some(v); }
                            'i' => { o.image = Some(get_one(&mut p, inline)); }
                            _ => { let v = get_one(&mut p, inline); validate(&v, OUTPUTS, "output <FORMAT>")?; o.output = Some(v); }
                        }
                        consumed = true;
                        break;
                    }
                    _ => return Err(err_unexpected(&format!("-{}", c))),
                }
                k += 1;
            }
            let _ = consumed;
            continue;
        }
        pos.push(a);
    }
    if pos.len() > 1 { return Err(err_unexpected(&pos[1])); }
    o.path = pos.into_iter().next();
    o.number_of_authors = num_authors;
    o.number_of_languages = num_languages;
    o.number_of_file_churns = num_churns;
    Ok(Action::Run(Box::new(o)))
}

fn get_one(p: &mut P, inline: Option<String>) -> String {
    match inline { Some(v) => v, None => p.next().unwrap_or_default() }
}

fn get_num(p: &mut P, inline: Option<String>, opt: &str) -> Result<usize, String> {
    let v = get_one(p, inline);
    match v.parse::<usize>() {
        Ok(n) => Ok(n),
        Err(_) => Err(err_num(&v, opt)),
    }
}

fn get_list(p: &mut P, inline: Option<String>, multi: bool) -> Result<Vec<String>, String> {
    let mut out = Vec::new();
    match inline {
        Some(v) => { for x in v.split(',') { out.push(x.to_string()); } }
        None => {
            if multi {
                while p.has() && !p.peek().unwrap().starts_with('-') { out.push(p.next().unwrap()); }
            } else {
                if let Some(v) = p.next() { out.push(v); }
            }
        }
    }
    Ok(out)
}

fn get_colors(p: &mut P, inline: Option<String>, opt: &str) -> Result<Vec<u8>, String> {
    let mut out = Vec::new();
    match inline {
        Some(v) => { for x in v.split(',') { out.push(parse_color(x, opt)?); } }
        None => {
            while p.has() && !p.peek().unwrap().starts_with('-') {
                let v = p.next().unwrap();
                out.push(parse_color(&v, opt)?);
            }
        }
    }
    Ok(out)
}

fn parse_color(v: &str, opt: &str) -> Result<u8, String> {
    match v.parse::<u8>() {
        Ok(n) if n < 16 => Ok(n),
        _ => Err(err_invalid_range(v, opt)),
    }
}

fn validate(v: &str, possible: &[&str], opt: &str) -> Result<(), String> {
    if possible.contains(&v) { Ok(()) } else { Err(err_invalid(v, opt, possible)) }
}
