    }
    if !disabled(o, "head") {
        let refs: Vec<String> = info.head_refs.iter().map(|r| format!("        {}", q(r))).collect();
        fields.push(format!("    {{\n      \"HeadInfo\": {\n        \"headRefs\": {{\n          \"shortCommitId\": {},\n          \"refs\": [\n{}\n          ]\n        }}\n      }}\n    }}", q(&info.head_id), refs.join(",\n")));
    }
    if !disabled(o, "pending") {
        fields.push(format!("    {{\n      \"PendingInfo\": {{\n        \"added\": {},\n        \"deleted\": {},\n        \"modified\": {}\n      }}\n    }}", info.pending.0, info.pending.1, info.pending.2));
    }
    if !disabled(o, "version") {
        fields.push(format!("    {{\n      \"VersionInfo\": {{\n        \"version\": {}\n      }}\n    }}", q(&info.version)));
    }
    if !disabled(o, "created") {
        fields.push(format!("    {{\n      \"CreatedInfo\": {{\n        \"creationDate\": {}\n      }}\n    }}", q(&info.created)));
    }
    if !disabled(o, "dependencies") {
        fields.push(format!("    {{\n      \"DependenciesInfo\": {{\n        \"dependencies\": {}\n      }}\n    }}", q(&dep_str(info))));
    }
    if !disabled(o, "languages") {
        let items: Vec<String> = info.languages.iter().map(|(n, p)| format!("      {{\n        \"language\": {},\n        \"percentage\": {}\n      }}", q(n), fmt_f64(*p))).collect();
        fields.push(format!("    {{\n      \"LanguagesInfo\": {{\n        \"languagesWithPercentage\": [\n{}\n        ]\n      }}\n    }}", items.join(",\n")));
    }
    if !disabled(o, "authors") {
        let items: Vec<String> = info.authors.iter().map(|(n, e, c, p)| {
            let em = match e { Some(e) => q(e), None => "null".to_string() };
            format!("        {{\n          \"name\": {},\n          \"email\": {},\n          \"nbrOfCommits\": {},\n          \"contribution\": {}\n        }}", q(n), em, c, p)
        }).collect();
        fields.push(format!("    {{\n      \"AuthorsInfo\": {{\n        \"authors\": [\n{}\n        ]\n      }}\n    }}", items.join(",\n")));
    }
    if !disabled(o, "last-change") {
        fields.push(format!("    {{\n      \"LastChangeInfo\": {{\n        \"lastChange\": {}\n      }}\n    }}", q(&info.last_change)));
    }
    if !disabled(o, "contributors") {
        fields.push(format!("    {{\n      \"ContributorsInfo\": {{\n        \"totalNumberOfAuthors\": {}\n      }}\n    }}", info.contributors));
    }
    if !disabled(o, "url") {
        fields.push(format!("    {{\n      \"UrlInfo\": {{\n        \"repoUrl\": {}\n      }}\n    }}", q(&info.url)));
    }
    if !disabled(o, "commits") {
        fields.push(format!("    {{\n      \"CommitsInfo\": {{\n        \"numberOfCommits\": {},\n        \"isShallow\": {}\n      }}\n    }}", info.commits, info.shallow));
    }
    if !disabled(o, "churn") {
        let items: Vec<String> = info.churn.iter().map(|(f, c)| format!("      {{\n        \"filePath\": {},\n        \"nbrOfCommits\": {}\n      }}", q(f), c)).collect();
        fields.push(format!("    {{\n      \"ChurnInfo\": {{\n        \"file_churns\": [\n{}\n        ],\n        \"churn_pool_size\": {}\n      }}\n    }}", items.join(",\n"), info.churn_pool));
    }
    if !disabled(o, "lines-of-code") {
