}

fn fmt_f64(v: f64) -> String {
    if v == v.trunc() { format!("{:.1}", v) } else { format!("{}", v) }
}

fn dep_str(info: &Info) -> String {
    if info.deps_count > 0 { format!("{} ({})", info.deps_count, info.deps_pm) } else { String::new() }
}

fn disabled(o: &Opts, n: &str) -> bool { o.disabled.iter().any(|d| d == n) }

pub fn yaml_quote(s: &str) -> String {
    if s.is_empty() { return "''".to_string(); }
    if s.chars().all(|c| c.is_ascii_alphanumeric() || " ._/-~+".contains(c)) && !s.starts_with('-') {
        return s.to_string();
    }
    let mut out = String::from("'");
    for c in s.chars() {
        if c == '\'' { out.push_str("''"); } else { out.push(c); }
    }
    out.push('\'');
    out
}

pub fn render_yaml(info: &Info, o: &Opts) -> String {
    let mut s = String::new();
    s.push_str("title:\n");
    s.push_str(&format!("  gitUsername: {}\n", yaml_quote(&info.username)));
    s.push_str(&format!("  gitVersion: {}\n", yaml_quote(&info.git_version)));
    s.push_str("infoFields:\n");
    if !disabled(o, "project") {
        s.push_str("- ProjectInfo:\n");
        s.push_str(&format!("    repoName: {}\n", yaml_quote(&info.repo_name)));
        s.push_str(&format!("    numberOfBranches: {}\n", info.branches));
        s.push_str(&format!("    numberOfTags: {}\n", info.tags));
    }
    if !disabled(o, "description") {
        s.push_str("- DescriptionInfo:\n");
        match &info.description { Some(d) => s.push_str(&format!("    description: {}\n", yaml_quote(d))), None => s.push_str("    description: null\n") }
    }
    if !disabled(o, "head") {
        s.push_str("- HeadInfo:\n");
        s.push_str("    headRefs:\n");
        s.push_str(&format!("      shortCommitId: {}\n", yaml_quote(&info.head_id)));
        s.push_str("      refs:\n");
        for r in &info.head_refs { s.push_str(&format!("      - {}\n", yaml_quote(r))); }
    }
    if !disabled(o, "pending") {
        s.push_str("- PendingInfo:\n");
        s.push_str(&format!("    added: {}\n", info.pending.0));
        s.push_str(&format!("    deleted: {}\n", info.pending.1));
        s.push_str(&format!("    modified: {}\n", info.pending.2));
    }
    if !disabled(o, "version") {
        s.push_str("- VersionInfo:\n");
        s.push_str(&format!("    version: {}\n", yaml_quote(&info.version)));
    }
    if !disabled(o, "created") {
        s.push_str("- CreatedInfo:\n");
        s.push_str(&format!("    creationDate: {}\n", yaml_quote(&info.created)));
    }
    if !disabled(o, "dependencies") {
        s.push_str("- DependenciesInfo:\n");
        s.push_str(&format!("    dependencies: {}\n", yaml_quote(&dep_str(info))));
    }
    if !disabled(o, "languages") {
        s.push_str("- LanguagesInfo:\n");
        s.push_str("    languagesWithPercentage:\n");
        for (n, p) in &info.languages {
            s.push_str("    - language: ");
            s.push_str(&yaml_quote(n));
            s.push('\n');
            s.push_str(&format!("      percentage: {}\n", fmt_f64(*p)));
        }
    }
    if !disabled(o, "authors") {
        s.push_str("- AuthorsInfo:\n");
        s.push_str("    authors:\n");
        for (n, e, c, p) in &info.authors {
            s.push_str("    - name: ");
            s.push_str(&yaml_quote(n));
            s.push('\n');
            match e { Some(e) => s.push_str(&format!("      email: {}\n", yaml_quote(e))), None => s.push_str("      email: null\n") }
            s.push_str(&format!("      nbrOfCommits: {}\n", c));
            s.push_str(&format!("      contribution: {}\n", p));
        }
    }
    if !disabled(o, "last-change") {
        s.push_str("- LastChangeInfo:\n");
        s.push_str(&format!("    lastChange: {}\n", yaml_quote(&info.last_change)));
    }
    if !disabled(o, "contributors") {
        s.push_str("- ContributorsInfo:\n");
        s.push_str(&format!("    totalNumberOfAuthors: {}\n", info.contributors));
    }
    if !disabled(o, "url") {
        s.push_str("- UrlInfo:\n");
        s.push_str(&format!("    repoUrl: {}\n", yaml_quote(&info.url)));
    }
    if !disabled(o, "commits") {
        s.push_str("- CommitsInfo:\n");
        s.push_str(&format!("    numberOfCommits: {}\n", info.commits));
        s.push_str(&format!("    isShallow: {}\n", info.shallow));
    }
    if !disabled(o, "churn") {
        s.push_str("- ChurnInfo:\n");
        s.push_str("    file_churns:\n");
        for (f, c) in &info.churn {
            s.push_str("    - filePath: ");
            s.push_str(&yaml_quote(f));
            s.push('\n');
            s.push_str(&format!("      nbrOfCommits: {}\n", c));
        }
        s.push_str(&format!("    churn_pool_size: {}\n", info.churn_pool));
    }
    if !disabled(o, "lines-of-code") {
        s.push_str("- LocInfo:\n");
        s.push_str(&format!("    linesOfCode: {}\n", info.loc));
    }
    if !disabled(o, "size") {
        s.push_str("- SizeInfo:\n");
        s.push_str(&format!("    repoSize: {}\n", yaml_quote(&crate::render::format_size(info.size, &o.number_separator))));
        s.push_str(&format!("    fileCount: {}\n", info.file_count));
    }
    if !disabled(o, "license") {
        s.push_str("- LicenseInfo:\n");
        s.push_str(&format!("    license: {}\n", yaml_quote(&info.license)));
    }
    s
}
