use crate::info::{Info, Opts};

pub fn sub(tpl: &str, args: &[&str]) -> String {
    let mut out = String::new();
    let mut ai = 0;
    let b: Vec<char> = tpl.chars().collect();
    let mut i = 0;
    while i < b.len() {
        if b[i] == '{' && i + 1 < b.len() && b[i + 1] == '}' {
            out.push_str(args.get(ai).map(|s| s.as_str()).unwrap_or(""));
            ai += 1;
            i += 2;
            continue;
        }
        out.push(b[i]);
        i += 1;
    }
    out
}

pub fn json_escape(s: &str) -> String {
    let mut out = String::new();
    for c in s.chars() {
        match c {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            c if (c as u32) < 0x20 => out.push_str(&format!("\\u{:04x}", c as u32)),
            c => out.push(c),
        }
    }
    out
}

pub fn q(s: &str) -> String { format!("\"{}\"", json_escape(s)) }

