use crate::lang::{Color, ARTS, LANGS, LangStat};
use crate::info::{Info, Opts};
use crate::json::sub;

pub struct W {
    pub out: String,
    pub truecolor: bool,
    pub bold: bool,
}

impl W {
    pub fn new(truecolor: bool, bold: bool) -> Self { W { out: String::new(), truecolor, bold } }
    pub fn seg(&mut self, c: &Color, t: &str) {
        self.out.push_str(&c.escape(self.truecolor, self.bold));
        self.out.push_str(t);
        self.out.push_str("\x1b[0m");
    }
    pub fn plain(&mut self, t: &str) { self.out.push_str(t); }
}

pub fn hexval(c: char) -> usize {
    match c { '0'..='9' => c as usize - '0' as usize, 'a'..='f' => c as usize - 'a' as usize + 10, _ => 0 }
}

pub fn format_size(bytes: u64, sep: &str) -> String {
    let units = ["B", "KiB", "MiB", "GiB", "TiB"];
    let mut v = bytes as f64;
    let mut i = 0;
    while v >= 1024.0 && i < units.len() - 1 { v /= 1024.0; i += 1; }
    if i == 0 { return format!("{} {}", with_sep(bytes, sep), units[0]); }
    format!("{:.2} {}", v, units[i])
}

pub fn with_sep(n: u64, sep: &str) -> String {
    let s = n.to_string();
    if sep == "plain" { return s; }
    let ch = match sep { "comma" => ',', "space" => ' ', "underscore" => '_', _ => ' ' };
    let b: Vec<char> = s.chars().collect();
    let mut out = String::new();
    for (i, c) in b.iter().enumerate() {
        if i > 0 && (b.len() - i) % 3 == 0 { out.push(ch); }
        out.push(*c);
    }
    out
}

type Seg = (Option<Color>, String);

fn art_def_for(slug: &str) -> Option<&'static crate::langdata::ArtDef> {
    ARTS.iter().find(|a| a.w > 0 && std::ptr::eq(a, art_ptr(slug)))
}

fn art_ptr(slug: &str) -> &'static crate::langdata::ArtDef {
    let idx = LANGS.iter().position(|l| l.slug == slug).unwrap_or(0);
    &ARTS[idx]
}

pub struct ArtBlock {
    pub lines: Vec<Vec<(usize, String)>>,
    pub w: usize,
    pub colors: Vec<Color>,
}

pub fn build_art(info: &Info, o: &Opts, truecolor: bool) -> Option<ArtBlock> {
    if o.no_art { return None; }
    let slug: String = if let Some(l) = &o.ascii_language {
        l.clone()
    } else {
        match info.art_lang { Some(i) => LANGS[i].slug.to_string(), None => return None }
    };
    let a = art_def_for(&slug)?;
    let mut colors: Vec<Color> = if truecolor { a.true_colors.to_vec() } else { a.ansi_colors.to_vec() };
    if let Some(cs) = &o.ascii_colors {
        for (i, c) in cs.iter().enumerate() {
            if i < colors.len() { colors[i] = Color::Ansi(*c); }
        }
    }
    let mut lines = Vec::new();
    for l in a.lines {
        let mut row = Vec::new();
        for part in l.split('\u{1}') {
            let idx = hexval(part.chars().next().unwrap_or('0'));
            row.push((idx, part[1..].to_string()));
        }
        lines.push(row);
    }
    Some(ArtBlock { lines, w: a.w, colors })
}

fn art_text_colors(o: &Opts, info: &Info, truecolor: bool) -> Option<Color> {
    if let Some(inp) = &o.ascii_input { let _ = inp; return Some(Color::Default); }
    let b = build_art(info, o, truecolor)?;
    b.colors.first().cloned()
}

pub fn render_terminal(w: &mut W, info: &Info, o: &Opts) {
    let base0 = art_text_colors(o, info, w.truecolor).unwrap_or(Color::Ansi(7));
    let tc = text_colors(o, &base0);
    let (title_c, tilde_c, underline_c, subtitle_c, colon_c, info_c) = (tc[0], tc[1], tc[2], tc[3], tc[4], tc[5]);

    let mut rows: Vec<Vec<Seg>> = Vec::new();
    if !o.no_title {
        let mut r: Vec<Seg> = Vec::new();
        r.push((Some(title_c), info.username.clone()));
        if !info.git_version.is_empty() {
            r.push((None, " ".to_string()));
            r.push((Some(tilde_c), "~".to_string()));
            r.push((None, " ".to_string()));
            r.push((Some(title_c), info.git_version.clone()));
        } else {
            r.push((Some(title_c), String::new()));
        }
        rows.push(r);
    }
    {
        let mut title = String::new();
        if !o.no_title {
            title.push_str(&info.username);
            if !info.git_version.is_empty() {
                title.push_str(" ~ ");
                title.push_str(&info.git_version);
            }
        }
        let n = title.chars().count();
        let dashes: String = std::iter::repeat('-').take(n).collect();
        rows.push(vec![(Some(underline_c), dashes), (Some(underline_c), String::new())]);
    }
    let info_rows = build_info_rows(info, o, &subtitle_c, &colon_c, &info_c, w);
    let mut k = 0usize;
    for r in info_rows { let _ = k; rows.push(r); }
    let ninfo = rows.len();
    let art = if o.ascii_input.is_some() {
        let inp = o.ascii_input.clone().unwrap_or_default();
        let mut lines = Vec::new();
        for l in inp.split('\n') { lines.push(vec![(0usize, l.to_string())]); }
        let wmax = lines.iter().map(|l| l[0].1.chars().count()).max().unwrap_or(0);
        Some(ArtBlock { lines, w: wmax, colors: vec![Color::Default] })
    } else { build_art(info, o, w.truecolor) };
    let art_n = art.as_ref().map(|a| a.lines.len()).unwrap_or(0);
    let palette_row = if art_n > 0 {
        if art_n - 1 >= ninfo { art_n - 1 } else { ninfo + 1 }
    } else { ninfo + 1 };
    let total = std::cmp::max(palette_row + 1, std::cmp::max(ninfo, art_n));
    let mut out_rows: Vec<Vec<Seg>> = Vec::new();
    for i in 0..total {
        let mut r: Vec<Seg> = Vec::new();
        if let Some(a) = &art {
            if i < a.lines.len() {
                r.push((Some(Color::Default), String::new()));
                for (idx, txt) in &a.lines[i] {
                    let c = a.colors.get(*idx).cloned().unwrap_or(Color::Default);
                    r.push((Some(c), txt.clone()));
                }
            }
            // pad
            let cur: usize = r.iter().map(|(_, t)| t.chars().count()).sum();
            if cur < a.w { r.push((None, " ".repeat(a.w - cur))); }
        }
        if i < ninfo {
            for s in &rows[i] { r.push(s.clone()); }
        }
        if i == palette_row {
            for j in 0..8u8 {
                r.push((Some(Color::Ansi(40 + j)), "   ".to_string()));
                r.push((Some(Color::Ansi(49)), String::new()));
            }
        }
        out_rows.push(r);
    }
    w.plain("\x1b[?7l");
    for (i, r) in out_rows.iter().enumerate() {
        if i > 0 { w.plain("\n"); }
        for (c, t) in r {
            match c { Some(col) => w.seg(col, t), None => w.plain(t) }
        }
    }
    w.plain("\n\x1b[?7h\n");
}

pub fn text_colors(o: &Opts, base0: &Color) -> [Color; 6] {
    let d = |i: usize, def: Color| -> Color {
        o.text_colors.as_ref().and_then(|v| v.get(i).map(|n| Color::Ansi(*n))).unwrap_or(def)
    };
    [d(0, base0.clone()), d(1, Color::Default), d(2, Color::Default), d(3, base0.clone()), d(4, Color::Default), d(5, Color::Default)]
}

fn lang_idx_at(info: &Info, pos: usize) -> usize { info.langs_idx.get(pos).cloned().unwrap_or(0) }

pub fn build_info_rows(info: &Info, o: &Opts, sub_c: &Color, colon_c: &Color, inf_c: &Color, w: &W)
    -> Vec<Vec<Seg>>
{
    let mut rows: Vec<Vec<Seg>> = Vec::new();
    let disabled = |n: &str| o.disabled.iter().any(|d| d == n);
    let inf = inf_c.clone();
    macro_rules! label {
        ($name:expr, $content:expr) => {{
            let mut first: Vec<Seg> = Vec::new();
            first.push((Some(sub_c.clone()), $name.to_string()));
            first.push((Some(colon_c.clone()), ":".to_string()));
            first.push((None, " ".to_string()));
            for s in $content { first.push(s); }
            rows.push(first);
        }};
    }
    macro_rules! cont {
        ($name:expr, $content:expr) => {{
            let mut r: Vec<Seg> = Vec::new();
            let ind = format!("{}: ", $name);
            r.push((Some(inf.clone()), ind));
            for s in $content { r.push(s); }
            rows.push(r);
        }};
    }
    let one = |s: String| vec![(Some(inf.clone()), s)];

    if !disabled("project") && (!info.repo_name.is_empty() || info.branches > 0 || info.tags > 0) {
        let mut s = info.repo_name.clone();
        if info.branches > 0 { s.push_str(&format!(" ({} branches)", info.branches)); }
        if info.tags > 0 { s.push_str(&format!(" ({} tags)", info.tags)); }
        label!("Project", one(s));
    }
    if !disabled("description") {
        if let Some(d) = &info.description { if !d.is_empty() { label!("Description", one(d.clone())); } }
    }
    if !disabled("head") {
        let mut s = info.head_id.clone();
        if !info.head_refs.is_empty() { s.push_str(&format!(" ({})", info.head_refs.join(", "))); }
        label!("HEAD", one(s));
    }
    if !disabled("pending") {
        let (a, d, m) = info.pending;
        let mut parts: Vec<String> = Vec::new();
        if m > 0 { parts.push(format!("{}+-", m)); }
        if a > 0 { parts.push(format!("{}+", a)); }
        if d > 0 { parts.push(format!("{}-", d)); }
        if !parts.is_empty() { label!("Pending", one(parts.join(" "))); }
    }
    if !disabled("version") && !info.version.is_empty() { label!("Version", one(info.version.clone())); }
    if !disabled("created") && !info.created.is_empty() { label!("Created", one(info.created.clone())); }
    if !disabled("dependencies") && info.deps_count > 0 {
        label!("Dependencies", one(format!("{} ({})", info.deps_count, info.deps_pm)));
    }
    if !disabled("languages") && !info.languages.is_empty() {
        let name = if info.languages.len() == 1 { "Language" } else { "Languages" };
        let n = info.languages.len();
        let take = std::cmp::min(o.number_of_languages, n);
        let mut shown: Vec<(i64, f64)> = (0..take).map(|i| (i as i64, info.languages[i].1)).collect();
        if n > take + 1 {
            let rest: f64 = info.languages[take..].iter().map(|x| x.1).sum();
            shown.push((-1, rest));
        } else if n > take {
            shown.push((take as i64, info.languages[take].1));
        }
        // bar
        let mut bar: Vec<Seg> = Vec::new();
        for (i, (idx, pct)) in shown.iter().enumerate() {
            let c = bar_color(w, *idx, i);
            let cells = (pct * 26.0 / 100.0).round() as usize;
            bar.push((Some(c), " ".repeat(cells)));
            bar.push((Some(Color::Ansi(49)), String::new()));
        }
        label!(name, bar);
        // legend
        let mut legend: Vec<Seg> = Vec::new();
        let indent = " ".repeat(name.len() + 2);
        for (i, (idx, pct)) in shown.iter().enumerate() {
            if i % 2 == 0 {
                if !legend.is_empty() { rows.push(legend); }
                legend = Vec::new();
                legend.push((Some(inf.clone()), indent.clone()));
            } else {
                legend.push((Some(inf.clone()), " ".to_string()));
            }
            let c = bar_color(w, *idx, i);
            let chip = if o.nerd_fonts && *idx >= 0 {
                LANGS[lang_idx_at(info, *idx as usize)].nerd.map(|c| c.to_string()).unwrap_or_else(|| "\u{25cf}".to_string())
            } else { "\u{25cf}".to_string() };
            legend.push((Some(c), chip));
            legend.push((Some(inf.clone()), " ".to_string()));
            let nm = if *idx < 0 { "Other".to_string() } else { LANGS[lang_idx_at(info, *idx as usize)].name.to_string() };
            legend.push((Some(inf.clone()), format!("{} ({:.1} %)", nm, pct)));
            legend.push((Some(inf.clone()), " ".to_string()));
        }
        if !legend.is_empty() { rows.push(legend); }
    }
    if !disabled("authors") && !info.authors.is_empty() {
        let name = if info.authors.len() == 1 { "Author" } else { "Authors" };
        let mut items: Vec<String> = Vec::new();
        for (n, e, c, pct) in info.authors.iter().take(o.number_of_authors) {
            let mut s = format!("{}% ", pct);
            s.push_str(n);
            if o.email { if let Some(e) = e { s.push_str(&format!(" <{}>", e)); } }
            s.push_str(&format!(" {}", c));
            items.push(s);
        }
        let mut it = items.into_iter();
        if let Some(f) = it.next() { label!(name, one(f)); }
        for p in it { cont!(name, one(p)); }
    }
    if !disabled("last-change") && !info.last_change.is_empty() { label!("Last change", one(info.last_change.clone())); }
    if !disabled("contributors") && info.contributors > 1 { label!("Contributors", one(info.contributors.to_string())); }
    if !disabled("url") && !info.url.is_empty() { label!("URL", one(info.url.clone())); }
    if !disabled("commits") && info.commits > 0 {
        let mut s = info.commits.to_string();
        if info.shallow { s.push_str(" (shallow)"); }
        label!("Commits", one(s));
    }
    if !disabled("churn") && !info.churn.is_empty() {
        let name = format!("Churn ({})", info.churn_pool);
        let mut items: Vec<String> = Vec::new();
        for (f, c) in &info.churn { items.push(format!("{} {}", f, c)); }
        let mut it = items.into_iter();
        if let Some(f) = it.next() { label!(name, one(f)); }
        for p in it { cont!(name, one(p)); }
    }
    if !disabled("lines-of-code") && info.loc > 0 {
        label!("Lines of code", one(with_sep(info.loc as u64, &o.number_separator)));
    }
    if !disabled("size") && info.file_count > 0 {
        let s = format!("{} ({} files)", format_size(info.size, &o.number_separator), with_sep(info.file_count as u64, &o.number_separator));
        label!("Size", one(s));
    }
    if !disabled("license") && !info.license.is_empty() { label!("License", one(info.license.clone())); }
    rows
}

fn bar_color(w: &W, idx: i64, pos: usize) -> Color {
    if idx < 0 { return Color::Ansi(7); }
    let li = idx as usize;
    if w.truecolor {
        let rgb = LANGS[li].rgb;
        Color::Rgb(rgb.0, rgb.1, rgb.2)
    } else {
        Color::Ansi((1 + pos % 6) as u8)
    }
}
