        s.push_str(&sub); s.push_str(name); s.push_str(rst);
        s.push_str(&colon); s.push(':'); s.push_str(rst);
        s.push(' ');
        s.push_str(&info_e); s.push_str(value); s.push_str(rst);
        rows.push(s);
