                cur.push(info_e.clone());
                cur.push(rst.to_string());
                rows.push(cur.join(""));
                cur = vec![format!("{}{}", info_e, indent)];
                nitems = 0;
            } else if nitems == 1 {
                cur.push(" ".to_string());
            }
            let c = bar_color(w, *idx, i);
            let chip = if o.nerd_fonts && *idx >= 0 {
                LANGS[lang_idx_at(info, *idx as usize)].nerd.map(|x| x.to_string()).unwrap_or_else(|| "\\u{25cf}".to_string())
            } else { "\\u{25cf}".to_string() };
            let nm = if *idx < 0 { "Other".to_string() } else { LANGS[lang_idx_at(info, *idx as usize)].name.to_string() };
            cur.push(format!("{}{}", c.escape(w.truecolor, w.bold), chip));
            cur.push(format!("{} ", info_e));
            cur.push(format!("{}{} (", info_e, nm));
            cur.push(format!("{:.1} %)", pct));
            cur.push(" ".to_string());
            nitems += 1;
        }
        if nitems > 0 {
            if nitems == 2 { cur.push(info_e.clone()); cur.push(rst.to_string()); }
            rows.push(cur.join(""));
        }
    }
    if !disabled("authors") && !info.authors.is_empty() {
        let name = if info.authors.len() == 1 { "Author" } else { "Authors" };
        let mut items: Vec<String> = Vec::new();
        for (n, e, c, pct) in info.authors.iter().take(o.number_of_authors) {
            let mut s = format!("{}% ", pct);
            s.push_str(n);
            if o.email { if let Some(e) = e { s.push_str(&format!(" <{}>", e)); } }
            s.push_str(&format!(" {}", c));
            items.push(s);
        }
        multi(&mut rows, name, &items);
    }
    if !disabled("last-change") && !info.last_change.is_empty() { label(&mut rows, "Last change", &info.last_change); }
    if !disabled("contributors") && info.contributors > 1 { label(&mut rows, "Contributors", &info.contributors.to_string()); }
    if !disabled("url") && !info.url.is_empty() { label(&mut rows, "URL", &info.url); }
    if !disabled("commits") && info.commits > 0 {
        let mut s = info.commits.to_string();
        if info.shallow { s.push_str(" (shallow)"); }
        label(&mut rows, "Commits", &s);
    }
    if !disabled("churn") && !info.churn.is_empty() {
        let name = format!("Churn ({})", info.churn_pool);
        let items: Vec<String> = info.churn.iter().map(|(f, c)| format!("{} {}", f, c)).collect();
        multi(&mut rows, &name, &items);
    }
    if !disabled("lines-of-code") && info.loc > 0 {
        label(&mut rows, "Lines of code", &with_sep(info.loc as u64, &o.number_separator));
    }
    if !disabled("size") && info.file_count > 0 {
        let s = format!("{} ({} files)", format_size(info.size, &o.number_separator), with_sep(info.file_count as u64, &o.number_separator));
        label(&mut rows, "Size", &s);
    }
    if !disabled("license") && !info.license.is_empty() { label(&mut rows, "License", &info.license); }
    rows
}

