        s.push_str(&title_c); s.push_str(&info.username); s.push_str(rst);
        if !info.git_version.is_empty() {
            s.push(' ');
            s.push_str(&tilde_c); s.push('~'); s.push_str(rst);
            s.push(' ');
            s.push_str(&title_c); s.push_str(&info.git_version); s.push_str(rst);
        } else {
            s.push_str(&title_c); s.push_str(rst);
        }
        rows.push(s);
    }
    // underline
    {
        let mut title = String::new();
        if !o.no_title {
            title.push_str(&info.username);
            if !info.git_version.is_empty() {
                title.push_str(" ~ ");
                title.push_str(&info.git_version);
            }
        }
        let n = title.chars().count();
        let dashes: String = std::iter::repeat('-').take(n).collect();
        let mut s = String::new();
        s.push_str(&ul_c); s.push_str(&dashes); s.push_str(&ul_c);
        rows.push(s);
    }
    let mut label = |rows: &mut Vec<String>, name: &str, value: &str| {
        let mut s = String::new();
        s.push_str(&sub); s.push_str(name); s.push_str(rst);
        s.push_str(&colon); s.push(':'); s.push_str(rst);
        s.push(' ');
        s.push_str(&info_e); s.push_str(value); s.push_str(rst);
        rows.push(s);
    };
    let mut cont = |rows: &mut Vec<String>, name: &str, value: &str| {
        let mut s = String::new();
        s.push_str(&info_e);
        s.push_str(&format!("{}: ", name));
        s.push_str(value); s.push_str(rst);
        rows.push(s);
    };
    let mut multi = |rows: &mut Vec<String>, name: &str, items: &[String]| {
        for (i, it) in items.iter().enumerate() {
            if i == 0 { label(rows, name, it); } else { cont(rows, name, it); }
        }
    };
    if !disabled("project") && (!info.repo_name.is_empty() || info.branches > 0 || info.tags > 0) {
        let mut s = info.repo_name.clone();
        if info.branches > 0 { s.push_str(&format!(" ({} branches)", info.branches)); }
        if info.tags > 0 { s.push_str(&format!(" ({} tags)", info.tags)); }
        label(&mut rows, "Project", &s);
    }
    if !disabled("description") {
        if let Some(d) = &info.description { if !d.is_empty() { label(&mut rows, "Description", d); } }
    }
    if !disabled("head") {
        let mut s = info.head_id.clone();
        if !info.head_refs.is_empty() { s.push_str(&format!(" ({})", info.head_refs.join(", "))); }
        label(&mut rows, "HEAD", &s);
    }
    if !disabled("pending") {
        let (a, d, m) = info.pending;
        let mut parts: Vec<String> = Vec::new();
        if m > 0 { parts.push(format!("{}+-", m)); }
        if a > 0 { parts.push(format!("{}+", a)); }
        if d > 0 { parts.push(format!("{}-", d)); }
        if !parts.is_empty() { label(&mut rows, "Pending", &parts.join(" ")); }
    }
    if !disabled("version") && !info.version.is_empty() { label(&mut rows, "Version", &info.version); }
    if !disabled("created") && !info.created.is_empty() { label(&mut rows, "Created", &info.created); }
    if !disabled("dependencies") && info.deps_count > 0 {
        label(&mut rows, "Dependencies", &format!("{} ({})", info.deps_count, info.deps_pm));
    }
    if !disabled("languages") && !info.languages.is_empty() {
        let name = if info.languages.len() == 1 { "Language" } else { "Languages" };
        let n = info.languages.len();
        let take = std::cmp::min(o.number_of_languages, n);
        let mut shown: Vec<(i64, f64)> = (0..take).map(|i| (i as i64, info.languages[i].1)).collect();
        if n > take + 1 {
            let rest: f64 = info.languages[take..].iter().map(|x| x.1).sum();
            shown.push((-1, rest));
        } else if n > take {
            shown.push((take as i64, info.languages[take].1));
        }
        // bar row
        {
            let mut s = String::new();
            s.push_str(&sub); s.push_str(name); s.push_str(rst);
            s.push_str(&colon); s.push(':'); s.push_str(rst);
            s.push(' ');
            s.push_str(&info_e); s.push_str(rst);
            for (i, (idx, pct)) in shown.iter().enumerate() {
                let c = bar_color(w, *idx, i);
                let cells = (pct * 26.0 / 100.0).round() as usize;
                s.push_str(&esc_bg(w, &c));
                s.push_str(&" ".repeat(cells));
                s.push_str("\x1b[49m");
            }
            s.push_str(rst);
            rows.push(s);
        }
        // legend rows
        let indent = " ".repeat(name.len() + 2);
        let mut cur: Vec<String> = Vec::new();
        let mut nitems = 0usize;
        for (i, (idx, pct)) in shown.iter().enumerate() {
            if nitems == 2 {
                // close row
                if nitems == 1 { cur.push(" ".to_string()); }
                cur.push(info_e.clone());
                cur.push(rst.to_string());
                rows.push(cur.join(""));
                cur = vec![format!("{}{}", info_e, indent)];
                nitems = 0;
            } else if nitems == 1 {
                cur.push(" ".to_string());
            }
            let c = bar_color(w, *idx, i);
            let chip = if o.nerd_fonts && *idx >= 0 {
                LANGS[lang_idx_at(info, *idx as usize)].nerd.map(|x| x.to_string()).unwrap_or_else(|| "\\u{25cf}".to_string())
            } else { "\\u{25cf}".to_string() };
            let nm = if *idx < 0 { "Other".to_string() } else { LANGS[lang_idx_at(info, *idx as usize)].name.to_string() };
            cur.push(format!("{}{}", c.escape(w.truecolor, w.bold), chip));
            cur.push(format!("{} ", info_e));
            cur.push(format!("{}{} (", info_e, nm));
            cur.push(format!("{:.1} %)", pct));
            cur.push(" ".to_string());
            nitems += 1;
        }
        if nitems > 0 {
            if nitems == 2 { cur.push(info_e.clone()); cur.push(rst.to_string()); }
            rows.push(cur.join(""));
        }
    }
    if !disabled("authors") && !info.authors.is_empty() {
        let name = if info.authors.len() == 1 { "Author" } else { "Authors" };
        let mut items: Vec<String> = Vec::new();
        for (n, e, c, pct) in info.authors.iter().take(o.number_of_authors) {
            let mut s = format!("{}% ", pct);
            s.push_str(n);
            if o.email { if let Some(e) = e { s.push_str(&format!(" <{}>", e)); } }
            s.push_str(&format!(" {}", c));
            items.push(s);
        }
        multi(&mut rows, name, &items);
    }
    if !disabled("last-change") && !info.last_change.is_empty() { label(&mut rows, "Last change", &info.last_change); }
    if !disabled("contributors") && info.contributors > 1 { label(&mut rows, "Contributors", &info.contributors.to_string()); }
    if !disabled("url") && !info.url.is_empty() { label(&mut rows, "URL", &info.url); }
    if !disabled("commits") && info.commits > 0 {
        let mut s = info.commits.to_string();
        if info.shallow { s.push_str(" (shallow)"); }
        label(&mut rows, "Commits", &s);
    }
    if !disabled("churn") && !info.churn.is_empty() {
        let name = format!("Churn ({})", info.churn_pool);
        let items: Vec<String> = info.churn.iter().map(|(f, c)| format!("{} {}", f, c)).collect();
        multi(&mut rows, &name, &items);
    }
    if !disabled("lines-of-code") && info.loc > 0 {
        label(&mut rows, "Lines of code", &with_sep(info.loc as u64, &o.number_separator));
    }
    if !disabled("size") && info.file_count > 0 {
        let s = format!("{} ({} files)", format_size(info.size, &o.number_separator), with_sep(info.file_count as u64, &o.number_separator));
        label(&mut rows, "Size", &s);
    }
    if !disabled("license") && !info.license.is_empty() { label(&mut rows, "License", &info.license); }
    rows
}

