{"command": "cat > /tmp/art4.py <<'PYEOF'
import subprocess, os, re, json, sys
slugs=[l.strip() for l in open('/tmp/slugs.txt') if l.strip()]
base='/tmp/artrepo'
ESC=re.compile(r'\x1b\[([0-9;]*)m')
def vis_len(s): return len(ESC.sub('', s))
def find_W(lines):
    for ln in lines:
        m=re.search(r'Lines of code', ln)
        if m:
            pre=ln[:m.start()]; k=pre.rfind('\x1b[')
            return vis_len(pre[:k])
    return None
def cut(ln, W):
    """return (art_str, info_str) splitting at W visible chars"""
    pos=0; vis=0
    while pos < len(ln):
        mm=ESC.match(ln,pos)
        if mm: pos=mm.end(); continue
        nxt=ESC.search(ln,pos); end=nxt.start() if nxt else len(ln)
        chunk=ln[pos:end]
        if vis+len(chunk) >= W:
            keep=W-vis
            return ln[:pos+keep], ln[pos+keep:]
        vis+=len(chunk); pos=end
    return ln, ''
def segs_from(s):
    segs=[]; cur=None; buf=''
    pos=0
    while pos < len(s):
        mm=ESC.match(s,pos)
        if mm:
            if cur is not None or buf!='': segs.append([cur,buf])
            cur=mm.group(1); buf=''; pos=mm.end()
        else:
            nxt=ESC.search(s,pos); end=nxt.start() if nxt else len(s)
            buf+=s[pos:end]; pos=end
    if cur is not None or buf!='': segs.append([cur,buf])
    return segs
CODE2IDX={'91':0,'92':1,'93':2,'94':3,'95':4,'96':5,'97':6,'30':7,'31':8,'32':9,'33':10,'34':11,'35':12,'36':13,'37':14,'90':15}
idx_of_c=lambda c: CODE2IDX.get((c or '').split(';')[0])
out={}
for slug in slugs:
    A=subprocess.run(['/workspace/executable','-a',slug,'--true-color','always'],cwd=base,capture_output=True,text=True).stdout
    C=subprocess.run(['/workspace/executable','-a',slug],cwd=base,capture_output=True,text=True).stdout
    D=subprocess.run(['/workspace/executable','-a',slug,'-c','9','10','11','12','13','14','15','0','1','2','3','4','5','6','7','8'],cwd=base,capture_output=True,text=True).stdout
    Alines=A.split('\n'); Clines=C.split('\n'); Dlines=D.split('\n')
    WA=find_W(Alines); WC=find_W(Clines); WD=find_W(Dlines)
    if not (WA==WC==WD) or WA is None:
        print('ERR', slug); continue
    pairs={}
    ok=True
    for la,lc,ld in zip(Alines,Clines,Dlines):
        if not la.startswith('\x1b'): continue
        if la.startswith('\x1b[?7l') or la.startswith('\x1b[?7h'): continue
        aa,ai=cut(la,WA); ca,ci=cut(lc,WA); da,di=cut(ld,WA)
        if ai or ci or di: ok=False; break   # only art lines (no info)
        sa=segs_from(aa); sc=segs_from(ca); sd=segs_from(da)
        if len(sa)!=len(sc) or len(sa)!=len(sd): ok=False; break
        for x,y,z in zip(sa,sc,sd):
            if x[1]!=y[1] or x[1]!=z[1]: ok=False; break
            idx=idx_of_c(z[0])
            pairs.setdefault(idx,set()).add((x[0],y[0]))
        if not ok: break
    if not ok: print('MISMATCH', slug); continue
    colors={}
    for idx,s in pairs.items():
        if idx is None: continue
        tr,an=list(s)[0]
        colors[idx]={'true':tr,'ansi':an}
    # now rebuild art lines with indices, using run A (true color) for text
    lines=[]
    for la in Alines:
        if not la.startswith('\x1b'): continue
        if la.startswith('\x1b[?7l') or la.startswith('\x1b[?7h'): continue
        aa,ai=cut(la,WA)
        if ai: break
        sa=segs_from(aa)
        # drop leading empty 39;1 prefix segment
        if sa and sa[0][0] in ('39;1','39') and sa[0][1]=='': sa=sa[1:]
        row=[]
        for c,t in sa:
            if c in ('0','','39','39;1'): continue
            row.append((idx_of_c(c), t))
        lines.append(row)
    out[slug]={'W':WA,'colors':colors,'lines':lines}
json.dump(out, open('/tmp/art4.json','w'), indent=0)
print('done', len(out))
print(out['python']['lines'][12], out['python']['lines'][14])
